import java.util.ArrayList;
import java.util.List;

public class Main {
    static double total(List<____> box) {
        double sum = 0;
        for (Number n : box) {
            sum = sum + n.doubleValue();
        }
        return sum;
    }

    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add(5);
        System.out.println(total(nums));
    }
}

