public class Main {
    static <T extends Comparable<T>> T biggest(T a, T b) {
        if (a.compareTo(b) >= 0) {
            return a;
        }
        return b;
    }

    public static void main(String[] args) {
        System.out.println(biggest(7, 21));
        System.out.println(biggest("小橘", "煤球"));
    }
}
